  ctx = gsap.context(() => {
    gsap.from('.d-flex', {
      x: -300,
      opacity: 0,
      duration: 1.2,
      ease: 'power2.out',
      stagger: 0.25,
      scrollTrigger: {
        trigger: servicesContent.value,   // Элемент, который активирует анимацию
